  {
   "name": "product_id",
   "type": "integer",
   "required": true,
   "description": "ID of the product to be returned.",
   "default": null,
   "constraints": []
  },
  {
   "name": "deliverer_id",
   "type": "integer",
   "required": true,
   "description": "ID of the deliverer assigned to the return.",
   "default": null,
   "constraints": []
  },
  {
   "name": "quantity",
   "type": "integer",
   "required": true,
   "description": "Quantity of the product to be returned.",
   "default": null,
   "constraints": [
    "value >= 1"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from amazon app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "return_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
